// src/modules/forecourt/infrastructure/configSync/worker.ts
var DEFAULT_POLL_MS = Number(
  process.env.FORECOURT_SYNC_POLL_MS || 10 * 6e4
);
function startForecourtConfigSyncWorker(opts) {
  const pollMs = Math.max(6e4, opts?.pollMs ?? DEFAULT_POLL_MS);
  const stationId2 = getStationId();
  let stopped = false;
  const loop = async () => {
    while (!stopped) {
      try {
        await upsertProcessHeartbeat({
          stationId: stationId2,
          processName: "forecourtConfigSyncWorker",
          status: "running",
          connected: true,
          metrics: { pollMs }
        }).catch(() => {
        });
        const cfg = await getForecourtSyncConfig(stationId2);
        if (!cfg?.enabled) {
          await new Promise((r) => setTimeout(r, pollMs));
          continue;
        }
        const res = await runForecourtConfigSync({
          stationId: stationId2,
          force: false,
          includeTankStatus: true
        });
        await upsertProcessHeartbeat({
          stationId: stationId2,
          processName: "forecourtConfigSyncWorker",
          status: res.ok ? "OK" : "ERROR",
          connected: true,
          metrics: {
            pollMs,
            lastResult: res.ok ? "ok" : "error",
            lastError: res.error
          }
        }).catch(() => {
        });
      } catch (err) {
        await upsertProcessHeartbeat({
          stationId: stationId2,
          processName: "forecourtConfigSyncWorker",
          status: "ERROR",
          connected: false,
          metrics: { pollMs },
          lastError: err?.message || String(err)
        }).catch(() => {
        });
      }
      await new Promise((r) => setTimeout(r, pollMs));
    }
  };
  loop();
  return {
    stop: () => {
      stopped = true;
    }
  };
}

