var HEARTBEAT_MS2 = 5e3;
var started2 = false;
async function claimNextBatch(limit = 5) {
  return await queryAll(
    `WITH claimed AS (
			SELECT id
			  FROM report_queue
			 WHERE status = 'PENDING'
			   AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())
			 ORDER BY created_at ASC
			 FOR UPDATE SKIP LOCKED
			 LIMIT $1
		)
		UPDATE report_queue rq
		   SET status = 'PROCESSING',
		       processing_started_at = NOW(),
		       updated_at = NOW()
		  FROM claimed
		 WHERE rq.id = claimed.id
		RETURNING rq.id, rq.station_id, rq.payload, rq.retry_count`,
    [limit]
  );
}
async function markDone(id) {
  await query(
    `UPDATE report_queue
		   SET status = 'DONE',
		       last_error = NULL,
		       next_attempt_at = NULL,
		       updated_at = NOW()
		 WHERE id = $1`,
    [id]
  );
}
async function markFailed(opts) {
  const { id, retryCount, maxRetries, errorMessage } = opts;
  const nextRetry = retryCount + 1;
  if (nextRetry >= maxRetries) {
    await query(
      `UPDATE report_queue
			   SET status = 'FAILED',
			       retry_count = $2,
			       last_error = $3,
			       next_attempt_at = NULL,
			       updated_at = NOW()
			 WHERE id = $1`,
      [id, nextRetry, errorMessage]
    );
    return;
  }
  const delaySeconds = calculateExponentialBackoffSeconds(nextRetry);
  await query(
    `UPDATE report_queue
		   SET status = 'PENDING',
		       retry_count = $2,
		       last_error = $3,
		       next_attempt_at = NOW() + ($4 || ' seconds')::interval,
		       updated_at = NOW()
		 WHERE id = $1`,
    [id, nextRetry, errorMessage, String(delaySeconds)]
  );
}
async function upsertReportFromResult(opts) {
  const {
    stationId: stationId2,
    sourceQueueId,
    reportType,
    reportDateTimeIso,
    payload,
    reference
  } = opts;
  const existing = await queryOne(
    `SELECT id FROM reports WHERE station_id = $1 AND source_queue_id = $2`,
    [stationId2, sourceQueueId]
  );
  if (existing?.id) return;
  await query(
    `INSERT INTO reports (id, station_id, report_date_time, report_type, payload, source_queue_id)
		 VALUES ($1, $2, $3, $4, $5, $6)`,
    [
      uuidv4(),
      stationId2,
      reportDateTimeIso,
      reportType,
      { ...payload, reference: reference ?? null },
      sourceQueueId
    ]
  );
}
function startReportQueueWorker(opts) {
  if (started2) return;
  started2 = true;
  const pollMs = Number(
    opts?.pollMs ?? process.env.VPOS_REPORT_WORKER_POLL_MS ?? process.env.VPOS_WORKER_POLL_MS ?? DEFAULT_POLL_MS4
  );
  const maxRetries = Number(
    opts?.maxRetries ?? process.env.VPOS_REPORT_MAX_RETRIES ?? 5
  );
  let lastHeartbeat = 0;
  let stop = false;
  (async () => {
    const gotLock = await tryAdvisoryLock2(`worker:${WORKER_NAME2}`);
    if (!gotLock) {
      return;
    }
    try {
      while (!stop) {
        const now = Date.now();
        if (now - lastHeartbeat > HEARTBEAT_MS2) {
          await upsertProcessHeartbeat({
            stationId: getStationId(),
            processName: WORKER_NAME2,
            metrics: { pollMs }
          });
          lastHeartbeat = now;
        }
        const batch = await claimNextBatch(5);
        if (!batch.length) {
          await new Promise((r) => setTimeout(r, pollMs));
          continue;
        }
        for (const item of batch) {
          try {
            const reportType = item.payload?.report_type ?? item.payload?.reportType ?? item.payload?.type ?? null;
            const result = await runReport({
              stationId: item.station_id,
              payload: item.payload,
              reportType,
              sourceQueueId: item.id
            });
            if (!result.ok) {
              await markFailed({
                id: item.id,
                retryCount: item.retry_count ?? 0,
                maxRetries,
                errorMessage: result.error
              });
              continue;
            }
            await upsertReportFromResult({
              stationId: item.station_id,
              sourceQueueId: item.id,
              reportType: result.reportType,
              reportDateTimeIso: result.reportDateTime,
              payload: result.payload,
              reference: result.reference ?? null
            });
            await markDone(item.id);
          } catch (e) {
            await markFailed({
              id: item.id,
              retryCount: item.retry_count ?? 0,
              maxRetries,
              errorMessage: String(e?.message || e)
            });
          }
        }
      }
    } finally {
      await advisoryUnlock2(`worker:${WORKER_NAME2}`);
    }
  })();
  return {
    stop: () => {
      stop = true;
    }
  };
}

