// src/modules/transactions/domain/transaction-errors.ts
var TransactionStatusTransitionError = class extends Error {
  constructor(currentStatus, nextStatus, message) {
    super(
      message || `Transaction status transition ${currentStatus ?? "UNKNOWN"} -> ${nextStatus} is not allowed`
    );
    this.currentStatus = currentStatus;
    this.nextStatus = nextStatus;
    this.code = "TRANSACTION_STATUS_TRANSITION_NOT_ALLOWED";
    this.name = "TransactionStatusTransitionError";
  }
};
var TransactionStatusNotFoundError = class extends Error {
  constructor(transactionId) {
    super(`Transaction ${transactionId} was not found`);
    this.transactionId = transactionId;
    this.code = "TRANSACTION_NOT_FOUND";
    this.name = "TransactionStatusNotFoundError";
  }
};

// src/modules/transactions/domain/transaction-policy.ts
var TRANSACTION_STATUS_TRANSITIONS = {
  OPEN: ["ALLOCATED", "PENDING", "FISCALIZING", "FAILED", "CANCELLED"],
  ALLOCATED: ["PENDING", "FISCALIZING", "FAILED", "CANCELLED"],
  PENDING: ["FISCALIZING", "FAILED", "FISCALIZED"],
  FAILED: ["PENDING", "FISCALIZING", "FAILED", "FISCALIZED"],
  FISCALIZING: ["FISCALIZED", "FAILED"],
  FISCALIZED: ["PRINTED", "REPRINTED", "CREDITED"],
  PRINTED: ["REPRINTED", "CREDITED"],
  REPRINTED: ["CREDITED"],
  CREDITED: [],
  CANCELLED: [],
  QUEUED: ["PENDING", "FAILED"],
  SENT: ["FISCALIZING", "FAILED", "FISCALIZED"],
  SUCCESS: [],
  REJECTED: ["FAILED"]
};
function canTransitionTransactionStatus(currentStatus, nextStatus) {
  if (!currentStatus) return true;
  if (currentStatus === nextStatus) return true;
  return (TRANSACTION_STATUS_TRANSITIONS[currentStatus] || []).includes(
    nextStatus
  );
}
function assertTransactionStatusTransition(currentStatus, nextStatus) {
  if (!canTransitionTransactionStatus(currentStatus, nextStatus)) {
    throw new TransactionStatusTransitionError(currentStatus, nextStatus);
  }
}

// src/modules/transactions/domain/transaction-status.ts
var TRANSACTION_STATUSES = [
  "OPEN",
  "ALLOCATED",
  "PENDING",
  "QUEUED",
  "SENT",
  "FISCALIZING",
  "FISCALIZED",
  "SUCCESS",
  "FAILED",
  "REJECTED",
  "CANCELLED",
  "PRINTED",
  "REPRINTED",
  "CREDITED"
];
var TRANSACTION_STATUS_SET = new Set(TRANSACTION_STATUSES);
function normalizeTransactionStatus(value) {
  const normalized = String(value ?? "").trim().toUpperCase();
  if (!normalized) return null;
  return TRANSACTION_STATUS_SET.has(normalized) ? normalized : null;
}

// src/modules/transactions/application/services/transaction-status-service.ts
function createTransactionStatusService(deps) {
  const { repository, auditLog } = deps;
  const loadSnapshot = async (stationId2, transactionId, context2) => {
    const snapshot = await repository.getStatusSnapshot({
      stationId: stationId2,
      transactionId,
      client: context2?.client ?? null
    });
    if (!snapshot || snapshot.deletedAt != null) {
      throw new TransactionStatusNotFoundError(transactionId);
    }
    return snapshot;
  };
  const transition = async (input) => {
    const snapshot = await loadSnapshot(
      input.stationId,
      input.transactionId,
      input
    );
    const currentStatus = normalizeTransactionStatus(snapshot.status);
    assertTransactionStatusTransition(currentStatus, input.nextStatus);
    const updated = await repository.persistStatus({
      stationId: input.stationId,
      transactionId: input.transactionId,
      nextStatus: input.nextStatus,
      expectedCurrentStatus: currentStatus,
      client: input.client ?? null,
      ...input.patch || {}
    });
    if (auditLog && currentStatus !== input.nextStatus) {
      await auditLog.recordTransactionStatusChange({
        stationId: input.stationId,
        transactionId: input.transactionId,
        previousStatus: currentStatus,
        nextStatus: input.nextStatus,
        actorId: input.actorId ?? null,
        metadata: input.metadata ?? null
      });
    }
    return updated;
  };
  return {
    transition,
    async assignCustomerAndMaybeAllocate(input) {
      const snapshot = await repository.getStatusSnapshot({
        stationId: input.stationId,
        transactionId: input.transactionId,
        client: input.client ?? null
      });
      if (!snapshot || snapshot.deletedAt != null) return null;
      const currentStatus = normalizeTransactionStatus(snapshot.status);
      const nextStatus = currentStatus === "OPEN" ? "ALLOCATED" : currentStatus;
      if (!nextStatus) {
        return await repository.persistStatus({
          stationId: input.stationId,
          transactionId: input.transactionId,
          nextStatus: "ALLOCATED",
          customerId: input.customerId,
          allocatedBy: input.allocatedBy ?? null,
          touchAllocatedAt: true,
          client: input.client ?? null
        });
      }
      if (currentStatus === "OPEN") {
        assertTransactionStatusTransition(currentStatus, nextStatus);
      }
      const updated = await repository.persistStatus({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus,
        expectedCurrentStatus: currentStatus,
        customerId: input.customerId,
        allocatedBy: input.allocatedBy ?? null,
        touchAllocatedAt: true,
        client: input.client ?? null
      });
      if (auditLog && currentStatus !== nextStatus) {
        await auditLog.recordTransactionStatusChange({
          stationId: input.stationId,
          transactionId: input.transactionId,
          previousStatus: currentStatus,
          nextStatus,
          actorId: input.allocatedBy ?? null,
          metadata: { customerId: input.customerId }
        });
      }
      return updated;
    },
    async retryFiscalization(input) {
      const snapshot = await repository.getStatusSnapshot({
        stationId: input.stationId,
        transactionId: input.transactionId,
        client: input.client ?? null
      });
      if (!snapshot || snapshot.deletedAt != null) return null;
      return await transition({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus: "PENDING",
        metadata: { reason: "retry-fiscalization" },
        client: input.client ?? null,
        patch: {
          clearLastError: true
        }
      });
    },
    async markFiscalizing(input) {
      return await transition({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus: "FISCALIZING",
        client: input.client ?? null
      });
    },
    async markFiscalized(input) {
      return await transition({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus: "FISCALIZED",
        client: input.client ?? null,
        patch: {
          fiscalizationReference: input.fiscalizationReference ?? null,
          fiscalizationResponse: input.fiscalizationResponse,
          fiscalDocumentId: input.fiscalDocumentId ?? null,
          touchFiscalizedAt: true,
          clearLastError: true
        }
      });
    },
    async markFailed(input) {
      return await transition({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus: "FAILED",
        client: input.client ?? null,
        patch: {
          lastError: input.lastError ?? null,
          incrementRetryCount: input.incrementRetryCount ?? false,
          fiscalDocumentId: input.fiscalDocumentId ?? null,
          fiscalizationResponse: input.fiscalizationResponse
        }
      });
    },
    async markCredited(input) {
      return await transition({
        stationId: input.stationId,
        transactionId: input.transactionId,
        nextStatus: "CREDITED",
        client: input.client ?? null
      });
    }
  };
}

