// src/modules/transactions/infrastructure/transactionQueueSql.ts
var transactionQueueSql = {
  claimNextBatch: `WITH claimed AS (
      SELECT id
        FROM transaction_queue
       WHERE status = 'PENDING'
         AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())
       ORDER BY created_at ASC
       FOR UPDATE SKIP LOCKED
       LIMIT $1
    )
    UPDATE transaction_queue tq
       SET status = 'PROCESSING',
           processing_started_at = NOW(),
           updated_at = NOW()
      FROM claimed
     WHERE tq.id = claimed.id
    RETURNING tq.id, tq.station_id, tq.payload, tq.retry_count, tq.transaction_id`,
  claimPendingForStation: `WITH picked AS (
      SELECT id
      FROM transaction_queue
      WHERE station_id = $1
        AND status = 'PENDING'
        AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())
      ORDER BY created_at ASC
      LIMIT $2
      FOR UPDATE SKIP LOCKED
    )
    UPDATE transaction_queue q
       SET status = 'PROCESSING',
           processing_started_at = NOW(),
           updated_at = NOW()
      FROM picked
     WHERE q.id = picked.id
    RETURNING q.id, q.station_id, q.payload, q.retry_count, q.transaction_id`,
  markDone: `UPDATE transaction_queue
     SET status = 'DONE',
         last_error = NULL,
         next_attempt_at = NULL,
         updated_at = NOW()
   WHERE id = $1`,
  markFailedTerminal: `UPDATE transaction_queue
     SET status = 'FAILED',
         retry_count = $2,
         last_error = $3,
         next_attempt_at = NULL,
         updated_at = NOW()
   WHERE id = $1`,
  requeuePendingWithDelay: `UPDATE transaction_queue
     SET status = 'PENDING',
         retry_count = $2,
         last_error = $3,
         next_attempt_at = NOW() + ($4 || ' seconds')::interval,
         updated_at = NOW()
   WHERE id = $1`,
  markFailedWithOptionalDelay: `UPDATE transaction_queue
     SET status = 'FAILED',
         retry_count = $2,
         last_error = $3,
         next_attempt_at = CASE
           WHEN $4::int IS NULL THEN NULL
           ELSE NOW() + ($4::int * INTERVAL '1 second')
         END,
         updated_at = NOW()
   WHERE id = $1`,
  resetStuckProcessing: `UPDATE transaction_queue
     SET status = 'PENDING',
         processing_started_at = NULL,
         updated_at = NOW()
   WHERE station_id = $1
     AND status = 'PROCESSING'
     AND processing_started_at < NOW() - ($2::int * INTERVAL '1 millisecond')`,
  requeueReadyFailures: `UPDATE transaction_queue
     SET status = 'PENDING',
         updated_at = NOW()
   WHERE station_id = $1
     AND status = 'FAILED'
     AND next_attempt_at IS NOT NULL
     AND next_attempt_at <= NOW()`,
  updatePayload: `UPDATE transaction_queue
     SET payload = $2::jsonb,
         updated_at = NOW()
   WHERE id = $1`,
  selectExistingTransactionByQueueId: `SELECT *
     FROM transactions
    WHERE station_id = $1
      AND source_queue_id = $2
      AND deleted_at IS NULL`,
  selectExistingTransactionById: `SELECT *
     FROM transactions
    WHERE id = $1
      AND station_id = $2
      AND deleted_at IS NULL`,
  enqueueForTransaction: `INSERT INTO transaction_queue (id, station_id, status, payload, transaction_id)
    VALUES ($1, $2, 'PENDING', $3::jsonb, $4)
    ON CONFLICT (station_id, transaction_id) WHERE transaction_id IS NOT NULL DO UPDATE
    SET status = CASE
                   WHEN transaction_queue.status IN ('PROCESSING', 'FAILED')
                   THEN transaction_queue.status
                   ELSE 'PENDING'
                 END,
        payload = EXCLUDED.payload,
        last_error = NULL,
        next_attempt_at = NULL,
        updated_at = NOW()`
};

// src/modules/transactions/infrastructure/transactionQueueRepo.ts
var transactionQueueRepo = {
  async claimNextBatch(limit = 5) {
    return await queryAll(
      transactionQueueSql.claimNextBatch,
      [limit]
    );
  },
  async claimPendingForStation(stationId2, limit) {
    return await queryAll(
      transactionQueueSql.claimPendingForStation,
      [stationId2, limit]
    );
  },
  async markDone(id) {
    await query(transactionQueueSql.markDone, [id]);
  },
  async markFailedTerminal(id, retryCount, errorMessage) {
    await query(transactionQueueSql.markFailedTerminal, [
      id,
      retryCount,
      errorMessage
    ]);
  },
  async requeuePendingWithDelay(id, retryCount, errorMessage, delaySeconds) {
    await query(transactionQueueSql.requeuePendingWithDelay, [
      id,
      retryCount,
      errorMessage,
      String(delaySeconds)
    ]);
  },
  async markFailedWithOptionalDelay(id, retryCount, errorMessage, delaySeconds) {
    await query(transactionQueueSql.markFailedWithOptionalDelay, [
      id,
      retryCount,
      errorMessage,
      delaySeconds
    ]);
  },
  async resetStuckProcessing(stationId2, stuckAfterMs) {
    await query(transactionQueueSql.resetStuckProcessing, [
      stationId2,
      stuckAfterMs
    ]);
  },
  async requeueReadyFailures(stationId2) {
    await query(transactionQueueSql.requeueReadyFailures, [stationId2]);
  },
  async updatePayload(id, payload) {
    await query(transactionQueueSql.updatePayload, [
      id,
      JSON.stringify(payload ?? null)
    ]);
  },
  async findTransactionByQueueId(stationId2, queueId) {
    return await queryOne(
      transactionQueueSql.selectExistingTransactionByQueueId,
      [stationId2, queueId]
    );
  },
  async findTransactionByTransactionId(transactionId, stationId2) {
    return await queryOne(
      transactionQueueSql.selectExistingTransactionById,
      [transactionId, stationId2]
    );
  },
  async enqueueForTransaction(stationId2, queueId, transactionId, payload) {
    await query(transactionQueueSql.enqueueForTransaction, [
      queueId,
      stationId2,
      JSON.stringify(payload ?? null),
      transactionId
    ]);
  }
};

// src/modules/transactions/infrastructure/fiscalization/transactionFiscalizationSchedulerWorker.ts
var WORKER_NAME3 = "transactionFiscalizationScheduler";
var DEFAULT_POLL_MS5 = 750;
async function claimEligibleTransactions(opts) {
  return await claimTransactionsForFiscalizationQueue(opts);
}
async function enqueueQueueRows(stationId2, ids) {
  for (const id of ids) {
    await transactionQueueRepo.enqueueForTransaction(stationId2, uuidv4(), id, {
      transactionId: id
    });
  }
}
function startTransactionFiscalizationSchedulerWorker(opts) {
  const pollMs = opts?.pollMs ?? DEFAULT_POLL_MS5;
  const batchSize = opts?.batchSize ?? 10;
  const stationId2 = getStationId();
  let stopped = false;
  let tickInFlight = false;
  async function tick() {
    if (stopped || tickInFlight) return;
    tickInFlight = true;
    try {
      const linkingWindowSeconds = await getStationLinkingWindowSeconds(stationId2);
      const claimed = await claimEligibleTransactions({
        stationId: stationId2,
        limit: batchSize,
        linkingWindowSeconds
      });
      if (claimed.length) {
        await enqueueQueueRows(
          stationId2,
          claimed.map((c) => c.id)
        );
      }
      await upsertProcessHeartbeat({
        stationId: stationId2,
        processName: WORKER_NAME3,
        pid: process.pid,
        status: "running",
        connected: true,
        metrics: {
          pollMs,
          batchSize,
          linkingWindowSeconds: linkingWindowSeconds ?? null,
          lastClaimed: claimed.length
        },
        lastError: null
      });
    } catch (e) {
      logger.error(`[${WORKER_NAME3}]`, {
        msg: "tick failed",
        error: e?.stack || e?.message || e
      });
      await upsertProcessHeartbeat({
        stationId: stationId2,
        processName: WORKER_NAME3,
        pid: process.pid,
        status: "running",
        connected: false,
        metrics: { pollMs, batchSize },
        lastError: String(e?.message || e)
      }).catch(() => {
      });
    } finally {
      tickInFlight = false;
    }
  }
  const timer = setInterval(() => tick().catch(() => {
  }), pollMs);
  tick().catch(() => {
  });
  return () => {
    stopped = true;
    clearInterval(timer);
  };
}

