// src/modules/fiscal-inbox/infrastructure/persistence/fiscal-inbox.sql.ts
function fiscalInboxListCountSql(whereSql) {
  return `SELECT COUNT(*)::bigint AS cnt FROM fiscal_inbox ${whereSql}`;
}
function fiscalInboxListRowsSql(whereSql, limitParamIndex, offsetParamIndex) {
  return `SELECT fi.id,
          fi.station_id,
          fi.topic,
          fi.status,
          fi.request_id,
          fi.attempt_count,
          fi.next_attempt_at,
          fi.received_at,
          fi.processed_at,
          fi.dead_at,
          fi.error_text,
          fi.message_json,
          tx.id AS related_transaction_id,
          tx.status AS related_transaction_status
     FROM fiscal_inbox fi
     LEFT JOIN transactions tx
       ON tx.station_id::text = fi.station_id::text
      AND tx.deleted_at IS NULL
      AND tx.id::text = COALESCE(
        NULLIF(fi.message_json->>'transactionId', ''),
        NULLIF(fi.request_id, '')
      )
     ${whereSql}
    ORDER BY fi.received_at DESC, fi.id DESC
    LIMIT $${limitParamIndex} OFFSET $${offsetParamIndex}`;
}
var fiscalInboxSql = {
  getById: `SELECT fi.id,
          fi.station_id,
          fi.topic,
          fi.request_id,
          fi.status,
          fi.attempt_count,
          fi.next_attempt_at,
          fi.received_at,
          fi.processed_at,
          fi.dead_at,
          fi.error_text,
          fi.message_json,
          tx.id AS related_transaction_id,
          tx.status AS related_transaction_status
     FROM fiscal_inbox fi
     LEFT JOIN transactions tx
       ON tx.station_id::text = fi.station_id::text
      AND tx.deleted_at IS NULL
      AND tx.id::text = COALESCE(
        NULLIF(fi.message_json->>'transactionId', ''),
        NULLIF(fi.request_id, '')
      )
    WHERE fi.id = $1
      AND fi.station_id::text = $2::text`,
  findByRequestId: `SELECT *
     FROM fiscal_inbox
    WHERE request_id::text = $1::text
      AND ($2::text IS NULL OR station_id::text = $2::text)
    ORDER BY received_at ASC, id ASC`,
  getNewestByRequestId: `SELECT id, received_at, status, topic, station_id, request_id
     FROM fiscal_inbox
    WHERE request_id::text = $1::text
      AND ($2::text IS NULL OR station_id::text = $2::text)
    ORDER BY received_at DESC, id DESC
    LIMIT 1`,
  getStatusSnapshot: `SELECT id, station_id, status, request_id
     FROM fiscal_inbox
    WHERE id = $1
      AND station_id::text = $2::text`,
  deleteById: `DELETE FROM fiscal_inbox
    WHERE id = $1
      AND station_id::text = $2::text
    RETURNING id`,
  requeueById: `UPDATE fiscal_inbox
      SET status = 'PENDING',
          attempt_count = 0,
          next_attempt_at = NOW(),
          dead_at = NULL,
          error_text = NULL,
          processed_at = NULL,
          updated_at = NOW()
    WHERE id = $1
      AND station_id::text = $2::text
    RETURNING id`,
  markDeadById: `UPDATE fiscal_inbox
      SET status = 'DEAD',
          dead_at = COALESCE(dead_at, NOW()),
          error_text = $3,
          updated_at = NOW()
    WHERE id = $1
      AND station_id::text = $2::text
    RETURNING id`,
  markFailedById: `UPDATE fiscal_inbox
      SET status = 'FAILED',
          error_text = $3,
          next_attempt_at = NOW(),
          updated_at = NOW()
    WHERE id = $1
      AND station_id::text = $2::text
    RETURNING id`,
  markProcessedById: `UPDATE fiscal_inbox
      SET status = 'PROCESSED',
          processed_at = COALESCE(processed_at, NOW()),
          updated_at = NOW()
    WHERE id = $1
      AND station_id::text = $2::text
    RETURNING id`,
  cloneSourceById: `SELECT station_id, topic, request_id, message_json
     FROM fiscal_inbox
    WHERE id = $1
      AND station_id::text = $2::text`,
  cloneInsert: `INSERT INTO fiscal_inbox (
      station_id,
      topic,
      request_id,
      status,
      attempt_count,
      next_attempt_at,
      received_at,
      processed_at,
      dead_at,
      error_text,
      message_json
    ) VALUES (
      $1, $2, $3,
      'PENDING',
      0,
      NOW(),
      NOW(),
      NULL,
      NULL,
      NULL,
      $4
    )
    RETURNING id`,
  enqueue: `INSERT INTO fiscal_inbox (station_id, topic, request_id, message_json, status)
    VALUES ($1, $2, $3, $4, 'PENDING')
    ON CONFLICT (station_id, topic, request_id)
      WHERE request_id IS NOT NULL
      DO UPDATE SET message_json = EXCLUDED.message_json,
                    status = 'PENDING',
                    attempt_count = 0,
                    next_attempt_at = NOW(),
                    dead_at = NULL,
                    error_text = NULL,
                    received_at = NOW(),
                    updated_at = NOW()
    RETURNING id`,
  claimBatch: `WITH batch AS (
       SELECT id
         FROM fiscal_inbox
        WHERE status IN ('PENDING','FAILED')
          AND next_attempt_at <= NOW()
          AND status <> 'DEAD'
        ORDER BY received_at ASC, id ASC
        LIMIT $1
        FOR UPDATE SKIP LOCKED
     )
     UPDATE fiscal_inbox fi
        SET status = 'PROCESSING',
            updated_at = NOW()
       FROM batch
      WHERE fi.id = batch.id
      RETURNING fi.id, fi.station_id, fi.topic, fi.request_id, fi.message_json, fi.attempt_count`,
  markDeliveryFailed: `UPDATE fiscal_inbox
      SET attempt_count = attempt_count + 1,
          error_text = $2,
          status = CASE
                    WHEN attempt_count + 1 >= $3 THEN 'DEAD'
                    ELSE 'FAILED'
                  END,
          dead_at = CASE
                    WHEN attempt_count + 1 >= $3 THEN NOW()
                    ELSE dead_at
                  END,
          next_attempt_at = CASE
                    WHEN attempt_count + 1 >= $3 THEN next_attempt_at
                    ELSE NOW() + (LEAST(900, POWER(2, GREATEST(0, attempt_count))) * INTERVAL '1 second')
                  END,
          processed_at = NULL,
          updated_at = NOW()
    WHERE id = $1`,
  metricsByStation: `SELECT
      COUNT(*) FILTER (WHERE status IN ('PENDING','FAILED') AND next_attempt_at <= NOW()) AS ready,
      COUNT(*) FILTER (WHERE status = 'PROCESSING') AS processing,
      COUNT(*) FILTER (WHERE status = 'DEAD') AS dead,
      MIN(received_at) FILTER (WHERE status IN ('PENDING','FAILED') AND next_attempt_at <= NOW()) AS oldest_ready_at,
      MIN(received_at) FILTER (WHERE status = 'DEAD') AS oldest_dead_at
    FROM fiscal_inbox
   WHERE station_id = $1`
};

// src/modules/fiscal-inbox/infrastructure/persistence/fiscal-inbox.repository.ts
function asPositiveInt(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.trunc(parsed) : fallback;
}
function asNonNegativeInt(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.trunc(parsed) : fallback;
}
function createFiscalInboxRepository() {
  return {
    async list(filters) {
      const stationId2 = String(filters.stationId || "").trim();
      if (!stationId2) throw new Error("stationId is required");
      const limit = Math.max(1, Math.min(500, asPositiveInt(filters.limit, 50)));
      const offset = Math.max(0, asNonNegativeInt(filters.offset, 0));
      const countWhere = ["station_id::text = $1::text"];
      const listWhere = ["fi.station_id::text = $1::text"];
      const params = [stationId2];
      const status = filters.status ?? "ANY";
      if (status && status !== "ANY") {
        params.push(status);
        countWhere.push(`status = $${params.length}`);
        listWhere.push(`fi.status = $${params.length}`);
      }
      const topic = filters.topic ?? "ANY";
      if (topic && topic !== "ANY") {
        params.push(topic);
        countWhere.push(`topic = $${params.length}`);
        listWhere.push(`fi.topic = $${params.length}`);
      }
      const countWhereSql = `WHERE ${countWhere.join(" AND ")}`;
      const listWhereSql = `WHERE ${listWhere.join(" AND ")}`;
      const totalRes = await query(
        fiscalInboxListCountSql(countWhereSql),
        params
      );
      const total = Number(totalRes.rows?.[0]?.cnt ?? 0);
      const listParams = [...params, limit, offset];
      const res = await query(
        fiscalInboxListRowsSql(
          listWhereSql,
          listParams.length - 1,
          listParams.length
        ),
        listParams
      );
      return {
        total,
        limit,
        offset,
        items: (res.rows ?? []).map((row) => mapFiscalInboxListItem(row))
      };
    },
    async getById(id, stationId2) {
      const res = await query(fiscalInboxSql.getById, [
        id,
        stationId2
      ]);
      return res.rows?.[0] ?? null;
    },
    async findByRequestId(requestId, stationId2) {
      const res = await query(fiscalInboxSql.findByRequestId, [
        requestId,
        stationId2 ?? null
      ]);
      return res.rows ?? [];
    },
    async getNewestByRequestId(requestId, stationId2) {
      const res = await query(fiscalInboxSql.getNewestByRequestId, [
        requestId,
        stationId2 ?? null
      ]);
      return res.rows?.[0] ?? null;
    },
    async getStatusSnapshot(input) {
      const res = await query(fiscalInboxSql.getStatusSnapshot, [
        input.id,
        input.stationId
      ]);
      const row = res.rows?.[0];
      if (!row) return null;
      return {
        id: Number(row.id),
        stationId: String(row.station_id ?? input.stationId),
        status: normalizeFiscalInboxStatus(row.status),
        requestId: row.request_id ? String(row.request_id) : null
      };
    },
    async requeueById(input) {
      const res = await query(
        fiscalInboxSql.requeueById,
        [input.id, input.stationId]
      );
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async markFailedById(input) {
      const res = await query(
        fiscalInboxSql.markFailedById,
        [input.id, input.stationId, input.errorText]
      );
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async markDeadById(input) {
      const res = await query(
        fiscalInboxSql.markDeadById,
        [input.id, input.stationId, input.errorText]
      );
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async markProcessedById(input) {
      const res = await query(
        fiscalInboxSql.markProcessedById,
        [input.id, input.stationId]
      );
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async deleteById(input) {
      const res = await query(
        fiscalInboxSql.deleteById,
        [input.id, input.stationId]
      );
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async cloneAndRequeue(input) {
      const srcRes = await query(fiscalInboxSql.cloneSourceById, [
        input.id,
        input.stationId
      ]);
      const src = srcRes.rows?.[0];
      if (!src) return null;
      const insertRes = await query(
        fiscalInboxSql.cloneInsert,
        [
          input.stationId,
          src.topic,
          input.requestId != null ? input.requestId : src.request_id,
          input.messageJson != null ? input.messageJson : src.message_json
        ]
      );
      return Number(insertRes.rows?.[0]?.id ?? 0) || null;
    },
    async exportRows(ids, stationId2) {
      const res = await query(
        `SELECT *
           FROM fiscal_inbox
          WHERE id = ANY($1::bigint[])
            AND ($2::text IS NULL OR station_id = $2::text)
          ORDER BY id ASC`,
        [ids, stationId2 ?? null]
      );
      return res.rows ?? [];
    },
    async exportRowsMetadata(ids, stationId2) {
      const res = await query(
        `SELECT id, station_id, topic, status, request_id, attempt_count, next_attempt_at, received_at, processed_at, dead_at, error_text
           FROM fiscal_inbox
          WHERE id = ANY($1::bigint[])
            AND ($2::text IS NULL OR station_id = $2::text)
          ORDER BY id ASC`,
        [ids, stationId2 ?? null]
      );
      return res.rows ?? [];
    },
    async bulkUpdate(input) {
      const stationFilter = input.stationId ? "AND station_id = $2::text" : "";
      const argsBase = [input.ids];
      if (input.stationId) argsBase.push(input.stationId);
      if (input.action === "REQUEUE") {
        await query(
          `UPDATE fiscal_inbox
              SET status='PENDING', attempt_count=0, next_attempt_at=NOW(), dead_at=NULL, processed_at=NULL, error_text=NULL
            WHERE id = ANY($1::bigint[]) ${stationFilter}`,
          argsBase
        );
        return { ok: true };
      }
      if (input.action === "MARK_FAILED") {
        const qargs = [...argsBase, input.errorText ?? null];
        await query(
          `UPDATE fiscal_inbox
              SET status='FAILED', next_attempt_at=NOW(), error_text = COALESCE($${qargs.length}::text, error_text)
            WHERE id = ANY($1::bigint[]) ${stationFilter}`,
          qargs
        );
        return { ok: true };
      }
      if (input.action === "MARK_DEAD") {
        const qargs = [...argsBase, input.errorText ?? null];
        await query(
          `UPDATE fiscal_inbox
              SET status='DEAD', dead_at=NOW(), error_text = COALESCE($${qargs.length}::text, error_text)
            WHERE id = ANY($1::bigint[]) ${stationFilter}`,
          qargs
        );
        return { ok: true };
      }
      if (input.action === "MARK_PROCESSED") {
        await query(
          `UPDATE fiscal_inbox
              SET status='PROCESSED', processed_at=NOW()
            WHERE id = ANY($1::bigint[]) ${stationFilter}`,
          argsBase
        );
        return { ok: true };
      }
      await query(
        `DELETE FROM fiscal_inbox
          WHERE id = ANY($1::bigint[]) ${stationFilter}`,
        argsBase
      );
      return { ok: true };
    },
    async bulkCloneAndRequeue(input) {
      const sourceRows = await query(
        `SELECT id, station_id, topic, request_id, message_json
           FROM fiscal_inbox
          WHERE id = ANY($1::bigint[])
            AND ($2::text IS NULL OR station_id = $2::text)
          ORDER BY id ASC`,
        [input.ids, input.stationId ?? null]
      );
      const created = [];
      for (const row of sourceRows.rows ?? []) {
        const baseMsg = row.message_json ?? {};
        const replace = input.override?.replace ?? null;
        const merge = input.override?.merge ?? null;
        const msg = replace ? replace : merge ? { ...baseMsg || {}, ...merge } : baseMsg;
        const newRequestId = row.request_id ? String(row.request_id) + String(input.requestIdSuffix ?? "") : null;
        const inserted = await query(
          `INSERT INTO fiscal_inbox (station_id, topic, request_id, message_json, status, attempt_count, next_attempt_at, dead_at)
           VALUES ($1, $2, $3, $4::jsonb, 'PENDING', 0, NOW(), NULL)
           RETURNING id, station_id, topic, request_id, status, received_at`,
          [row.station_id, row.topic, newRequestId, JSON.stringify(msg)]
        );
        if (inserted.rows?.[0]) created.push(inserted.rows[0]);
      }
      return { createdCount: created.length, created };
    },
    async requeueDead(input) {
      const res = await query(
        input.ids && input.ids.length ? `UPDATE fiscal_inbox
                SET status = 'PENDING',
                    attempt_count = 0,
                    next_attempt_at = NOW(),
                    dead_at = NULL,
                    error_text = NULL,
                    updated_at = NOW()
              WHERE station_id = $1
                AND status = 'DEAD'
                AND id = ANY($2::bigint[])
              RETURNING id` : `UPDATE fiscal_inbox
                SET status = 'PENDING',
                    attempt_count = 0,
                    next_attempt_at = NOW(),
                    dead_at = NULL,
                    error_text = NULL,
                    updated_at = NOW()
              WHERE station_id = $1
                AND status = 'DEAD'
              RETURNING id`,
        input.ids && input.ids.length ? [input.stationId, input.ids] : [input.stationId]
      );
      const requeued = (res.rows ?? []).map((row) => Number(row.id));
      return { requeuedCount: requeued.length, requeuedIds: requeued };
    },
    async enqueue(input) {
      const res = await query(fiscalInboxSql.enqueue, [
        input.stationId,
        input.topic,
        input.requestId != null ? String(input.requestId) : null,
        input.message ?? null
      ]);
      return Number(res.rows?.[0]?.id ?? 0) || null;
    },
    async claimBatch(limit) {
      const res = await query(fiscalInboxSql.claimBatch, [
        limit
      ]);
      return res.rows ?? [];
    },
    async markDeliveryFailed(input) {
      await query(fiscalInboxSql.markDeliveryFailed, [
        input.id,
        input.errorText,
        Math.max(1, Number(input.maxAttempts ?? 10))
      ]);
    },
    async getMetricsByStation(stationId2) {
      const res = await query(fiscalInboxSql.metricsByStation, [stationId2]);
      const row = res.rows?.[0];
      if (!row) return null;
      return {
        ready: Number(row.ready ?? 0),
        processing: Number(row.processing ?? 0),
        dead: Number(row.dead ?? 0),
        oldestReadyAt: row.oldest_ready_at ? String(row.oldest_ready_at) : null,
        oldestDeadAt: row.oldest_dead_at ? String(row.oldest_dead_at) : null
      };
    }
  };
}
var fiscalInboxRepository = createFiscalInboxRepository();

// src/modules/fiscal-inbox/application/commands/mark-fiscal-message-processed.ts
var fiscalInboxStatusService = createFiscalInboxStatusService({
  repository: fiscalInboxRepository
});
